custom_css:
/* 牛奶丝绸 - 烤冷面大王 */
/*
🌟自用二改依旧看🌷标注，禁止商用和二传，免费发布于尾巴镇
🌟想换背景图删最后的几行代码（有标注🌷🌷🌷和⬆️&⬇️部分）
🌟切页三元素+名字位移是正常的，关闭聊天重新进入即可*/



/* ====== 全局字体与变量 ====== */
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fbold.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A700%3Bfont-display%3Aswap%3B%7D%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
  font-family: "KingHwaOldSong";
  font-weight: normal;
}

/* 英文专用 ZSFT-bo */
#send_textarea,
.message-content,
.bubble-content,
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  font-family: "ZSFT-bo", "KingHwaOldSong", sans-serif !important;
}


:root {
/* Logo 图标变量 */
    --logo1: url('https://i.postimg.cc/8cTM37Ms/IMG-4860.png');
    --logo2: url('https://i.postimg.cc/y88nxbJj/IMG-4857.png');
    --logo3: url('https://i.postimg.cc/BQMcrBmr/IMG-4858.png');
    --logo4: url('https://i.postimg.cc/y88nxbJj/IMG-4857.png');
    --mbbg: url('https://i.postimg.cc/SKyXkBJy/IMG-4866.jpg');/*🌷面板背景不喜欢可以自己改*/
}

/*===顶栏部分===*/
#top-settings-holder {
    background-image: url('https://i.postimg.cc/8krnh9Pq/IMG-4866.jpg') !important;
    background-size: 100% 100% !important; 
    background-repeat: repeat !important; 
    background-position: center !important;
    background-attachment: scroll !important;
}

/* 删除顶栏阴影 */
#top-bar {
  box-shadow: none !important;
}
#top-bar::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: #fff !important;
    z-index: 1;
    pointer-events: auto;
}

#top-bar::after {
    content: "";
    position: fixed;
    top: -65px;
    right: 80px;
    width: 260px;
    height: 200px;
    background: transparent !important;
    z-index: 2;
    pointer-events: none;
}

/*图标替换*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}

#top-settings-holder .drawer { flex: 1; }

#top-settings-holder .drawer-icon {
    display: block;
    margin-top: 0px;
    background-color: transparent;
    border-radius: 0px !important;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 30px;
    height: 30px;
    opacity: 1 !important;
}

.drawer-icon.fa-fw:hover { transform: translateY(-1.5px); }

.drawer-icon.fa-sliders,
.drawer-icon.fa-user-cog,
.drawer-icon.fa-address-card {
    background-image: var(--logo2) !important;
}

.drawer-icon.fa-font,
.drawer-icon.fa-cubes {
  background-image: var(--logo1);
  transform: scale(0.8);
}

.drawer-icon.fa-plug,
.drawer-icon.fa-plug-circle-exclamation,
.drawer-icon.fa-book-atlas,
.drawer-icon.fa-panorama,
.drawer-icon.fa-face-smile {
    background-image: var(--logo3) !important;
}

/* 展开状态图标 */
#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: var(--logo4) !important; 
    transform: scale(1.2); 
}


/* 底栏整体背景 */
#send_form {
  background-image: url('https://i.postimg.cc/66gxKCyx/IMG-4866.jpg') !important;
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center center;
  border-radius: 8px !important;
  border: 1px solid transparent !important;
  padding: 8px;
}

/* 输入框 */
#send_textarea {
    border-radius: 6px !important;
    clip-path: none !important;
    background-color: #fff !important;
    border-color: transparent !important;
}

/* --- 底部按键图标替换 --- */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
    display: none !important;
}

#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
    width: 25px !important;
    height: 40px !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border-radius: 0px !important;
    opacity: 1 !important;
}

#options_button,
#extensionsMenuButton {
    background-image: var(--logo1) !important;
  transform: scale(0.8);
}

#send_but {
    background-image: var(--logo3) !important;
}

#quick-reply-rocket-button {
    background-image: var(--logo1) !important;
}

/* 输入框样式 */
#send_textarea {
    border-radius: 6px !important;
    clip-path: none !important;
    background-color: #fff !important; /* 纯白背景 */
    border-color: transparent !important;
}

/* ===== 输入框提示文字自定义 ===== */
#nonQRFormItems {
    position: relative;
}
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "SATIN";/*🌷可自改输入框文字*/
    color: #000 !important;
    position: absolute; 
    left: 52%;
    top: 40%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.45em; 
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}


/* --- 来自nini老师，默认隐藏 QR 按钮容器，并设置平滑过渡 --- */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

/* --- 输入框获得焦点时显示 QR 区域 --- */
#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

/* --- 新增：修复空白弹窗，仅隐藏空白背景，不影响点击 --- */
#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

/* --- 当输入框聚焦或激活时才显示 QR bar 内容 --- */
#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}



/*面板背景*/
.drawer-content {
    background: linear-gradient(rgba(255,255,255,0.5), rgba(255,255,255,0.5)), var(--mbbg) center/cover fixed no-repeat;
}




/*头像框*/
/* 来自hy老师，限制只在聊天消息区域内的头像显示头像框 */
#chat .mes .avatar {
    position: relative;
    border-radius: 50%;
    overflow: visible; /* 改为visible允许内容溢出 */
    flex-shrink: 0;
    z-index: 1;
}

#chat .mes .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 0%;/* 头像圆角，方角改为0 */
    position: relative;
    z-index: 1;
}

/* 添加头像框效果 - 只在聊天消息区域显示 */
#chat .mes .avatar::after {
    content: '';
    position: absolute;
    top: 50%;/* 🌷头像框位置，数字越大越往下 */
    left: 50%;/* 🌷头像框位置，数字越大越往右 */
    transform: translate(-50%, -50%);
    width: 390px; /* 🌷头像框宽 */
    height: 270px; /* 🌷头像框高 */
    background-image: url('https://i.postimg.cc/zGXnzHLX/IMG-4855.png'); /* 替换为您的头像框图片URL */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2; /* 确保头像框在头像之上 */
    pointer-events: none;
}

/*来自眠N老师*/
.mes {
    display: flex;
    flex-direction: column;
    align-items: center;
}
.mes .mesAvatarWrapper {
    display: flex;
    flex-wrap: wrap;
    justify-content: center !important;
    padding: 100px 0px 40px; /* 🌷头像的上、左右、下间距 */
    gap: 30px 50px; /* 🌷第一个是头像与下方元素的间距，第二个是楼层等元素之间的间距 */
}

/* 强制头像占据一整行，将其下方的元素推到下一行 */
.mes .mesAvatarWrapper .avatar {
    flex-basis: 100%;
    display: flex;
    justify-content: center;
}

/* 通用CSS */
.mes .mes_timer:empty,
.mes .mesIDDisplay:empty,
.mes .tokenCounterDisplay:empty {
    display: none;
}

.last_mes .mesAvatarWrapper {
    padding-bottom: 25px; /* 最后一条消息头像区域与下方间距，保持与前面一致 */
}



/*----🌷头像----*/
#chat .mes .avatar {
    position: relative;
  /*🌷大小⬇️*/
    width: 299px;
    height: 167px;

    border-radius: 50%;
    overflow: visible;
    flex-shrink: 0;
    z-index: 1;
}
.mes .avatar img {
    width: 100%; /* 头像图片宽度 */
    aspect-ratio: 16/9; /* 比例 */
    height: auto; 
    object-fit: cover;
    object-position: center 40%; /* 🌷Char头像显示区域 */ 
}

.mes[is_user="true"] .avatar img {
    object-position: center 25%; /* 🌷user头像显示区域 */
}



/*🌷名字*/
.name_text {
    position: absolute;
    left: 50%;/*🌷左右*/
    top:320px; /*🌷上下*/
    font-size: 15px;
    z-index: 11;
    transform: translateX(-50%);
}

/*🌷时间戳*/
.timestamp {
   position: absolute;
top: 293px; /*🌷上下*/
left: 50%; /*🌷左右*/
transform: translateX(-50%);
font-size: 12px;
z-index: 11;
}

/* 文本框与下一个头像框隔开 */
.mes {
    margin-bottom: 6em !important; 
    clear: both !important; 
}



/*聊天气泡 */
.mes .mes_block {
    background-color: rgba(255, 255, 255, 0.6) !important;
    border-radius: 12px !important;
    border: 1px solid rgba(235, 232, 215, 0.3) !important; 

}



/*文字铺满by墨千尾老师*/
.mes .mes_text {
    width: 100%;
    padding: 0px 5px 0px 0px;
    margin: 0px 0px 30px 0px;
}



/*——思维链——*/
#chat .mes .mes_reasoning_header {
    position: relative;
  /*🌷思维链位置⬇️*/
    margin-top: -33px !important;
    margin-left: 20px !important;
}


.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;
    --bottom-padding: 1rem;
    --left-padding: 0.1rem;
    --right-padding: 0.1rem;
    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/* 来自12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0;
    backdrop-filter: none !important; 
    -webkit-backdrop-filter: none !important; 
    padding: 0 !important;
    margin-bottom: 0 !important;
    color: var(--reasoning-text) !important;
    font-size: 1em !important;
    display: inline-flex !important;
    align-items: center !important;
    transition: none !important; 
}
/*来自hy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}
/*来自N老师*/
.mes_reasoning_header_title::before {
    content: "" !important;

  /*🌷思维链大小⬇️*/
    width: 40px !important;
    height: 40px !important;


    background-image: var(--logo4) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    display: inline-block !important;
    vertical-align: middle !important;
}
.mes_reasoning_header_title {
    font-size: 0 !important;
}


/*——图标统一替换 ——*/
/* 小铅笔 */
.fa-pencil-alt::before, .fa-pencil::before {
    display: none !important;
}
.fa-pencil-alt, .fa-pencil {
    background: var(--logo1) no-repeat center/contain !important;
    width: 25px !important;
    height: 25px !important;
    display: inline-block;
    vertical-align: middle;
    opacity: 1 !important;
    transition: opacity 0.3s ease !important;
  transform: scale(0.8);
    filter: grayscale(100%) contrast(120%) !important;
}

/* 三个点 */
.fa-ellipsis-h::before, .fa-ellipsis::before {
    display: none !important;
}
.fa-ellipsis-h, .fa-ellipsis {
    background: var(--logo3) no-repeat center/contain !important;
    width: 25px !important;
    height: 25px !important;
    display: inline-block;
    vertical-align: middle;
    opacity: 1 !important;
    transition: opacity 0.3s ease !important;
    filter: grayscale(100%) contrast(120%) !important;
}

.fa-pencil-alt:hover, 
.fa-pencil:hover, 
.fa-ellipsis-h:hover, 
.fa-ellipsis:hover {
    opacity: 0.7 !important;
}

/*滑块图标*/
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 25px !important;
    height: 25px !important;
    background: var(--logo3) center/contain no-repeat !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
    -webkit-filter: grayscale(100%) contrast(120%) !important;
}

/* 火狐兼容 */
input[type="range"]::-moz-range-thumb {
    appearance: none;
    width: 25px !important;
    height: 25px !important;
    background: var(--logo1) center/contain no-repeat !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
}

/*预设编辑*/
.neo-range-slider {
    height: 3px !important;
    background: #ccc !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    z-index: 1;
    margin-bottom: 0px !important;
    border-radius: 0px !important;
}

.prompt-manager-edit-action::before {
    display: none !important;
}
.prompt-manager-edit-action {
    background: var(--logo2) no-repeat center/25px 25px !important;
    width: 25px !important;
    height: 25px !important;
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
}

/*编辑按钮位置*/
.mes_buttons {
    position: relative;
    top: 0px;
    left: -10px;
}



/*---文字样式 ---*/
.mes {
    color: #000 !important;
}

/* 引用文本 */
.mes q {
    background: #f1f1f1 !important;
    color: #000 !important;
    border: 1px solid #ccc !important;
    padding: 5px 10px !important;
    font-style: normal !important;
    border-radius: 4px !important;
    box-shadow: none !important;
    display: inline-block !important;
}

/* 斜体文本 */
.mes i,
.mes em {
    color: #666 !important;
    text-decoration: underline !important;
}

/* 下划线文本 */
.mes u {
    text-decoration: none !important;
    color: #000 !important;
    font-weight: bold !important;
    padding: 3px 6px !important;
    border-radius: 4px !important;
    background: #e5e5e5 !important;
    border-bottom: none !important;
}




/*===来自12老师，收藏区左右滑动===*/
/* 收藏角色栏 */
#HotSwapWrapper {
    overflow: hidden;
}
#HotSwapWrapper > div {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    height: calc(var(--avatar-base-height) + 10px);
}

body.big-avatars #HotSwapWrapper > div {
    height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
#HotSwapWrapper > div::-webkit-scrollbar {
    height: 5px; 
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
    background-color: #666 !important; 
    border-radius: 5px; 
}

/* 收藏角色边框  */
.character_select.is_fav .avatar {
    outline: 2px solid #999 !important;
    box-shadow: 0 0 6px #999, 0 0 12px #666, 0 0 18px #555 !important;
}

/* 收藏角色名字  */
.character_select.is_fav .ch_name {
    color: #222 !important;
    text-shadow: 0 0 6px #999, 0 0 12px #666, 0 0 24px #555 !important;
}



/*——切页——*/
.swipe_left::before, .swipe_right::before { content: '' !important; }
.swipe_left:hover, .swipe_right:hover { transform: scale(1.1); }
.swipes-counter { 
    color: #333; 
    opacity: 1 !important; 
    transform: translateY(50px) !important;
}

.swipe_right, .swipe_left {
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: transform 0.2s ease;
    width: 20px;
    height: 30px;
    transform: translateY(50px) !important;
    filter: grayscale(100%) contrast(150%);
}

.swipe_right { background-image: var(--logo2);}
.swipe_left { background-image: var(--logo3); }



/* --- 折叠面板按键  --- */
.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 20px !important; 
    height: 20px !important; 
    background: transparent !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer;
    filter: none !important; 
    opacity: 1 !important; 
    color: #333 !important; 
    border: none !important; 
    box-shadow: none !important; 
}

.inline-drawer-icon::before {
    content: "" !important;
    display: block !important;
    background-image: var(--logo1) !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    width: 30px !important;
    height: 39px !important;
    color: transparent !important;
    filter: grayscale(100%) contrast(130%) !important;
    opacity: 1 !important; 
    text-shadow: none !important; 
}

.inline-drawer-icon:hover::before {
    transform: scale(1.2) !important;
}



/* 来自deleted user老师，加载动画 */
#preloader {
    position: fixed;
    margin: 0;
    padding: 0;
    top: 0;
    left: 0;
    z-index: 999999;
    width: 100vw;
    height: 100vh;
    background-color: #000;
    opacity: 1;
}

#load-spinner {
    --spinner-size: 85px;
    transition: none !important;
    opacity: 1 !important;
    top: calc(50% - var(--spinner-size) / 2);
    left: calc(50% - var(--spinner-size) / 2);
    position: absolute;
    width: var(--spinner-size);
    height: var(--spinner-size);
    background-image: var(--logo2) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    animation: moon-breath 3s ease-in-out infinite !important;
    transform: none !important;
}

@keyframes heartbeat {
    0%, 100% { transform: scale(1); opacity: 1; }
    15% { transform: scale(1.2); opacity: 0.9; }
    30% { transform: scale(1); opacity: 1; }
    45% { transform: scale(1.2); opacity: 0.9; }
    60% { transform: scale(1); opacity: 1; }
}

#load-spinner::before,
#load-spinner::after {
    display: none !important;
}




/*图标去灰 */
#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop {
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
    -webkit-filter: grayscale(100%) contrast(120%) !important;
}

#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#mes_stop i::before {
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
    -webkit-filter: grayscale(100%) contrast(120%) !important;
}

/*提示词管理 */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    color: #000 !important;
    background: #f5f5f5 !important;
    background-size: 100%;
    border-radius: 1px 1px 12px 12px;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    border-radius: 15px !important;
    padding: 5px !important;
}
.completion_prompt_manager_prompt .fa-asterisk,
.completion_prompt_manager_prompt .fa-square-poll-horizontal,
.completion_prompt_manager_prompt .fa-syringe,
.completion_prompt_manager_prompt .fa-thumb-tack,
.fa-xs.fa-solid.fa-robot {
    color: #333 !important;
}
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #666 !important;
