/* 来自咩咩咩咩咩咩野老师，全局隐藏 Webkit 系浏览器的滚动条 */
::-webkit-scrollbar {
  display: none;
}

/* Firefox 全局滚动条样式 */
html {
  scrollbar-width: thin; /* auto | thin | none */
  scrollbar-color: #888 #f1f1f1; /* 滑块颜色 轨道颜色 */
}


/* 去阴影 */
.fa-pencil-alt,
.fa-pencil,
.fa-ellipsis-h,
.fa-ellipsis,
.fa-pencil-alt:hover,
.fa-pencil:hover,
.fa-ellipsis-h:hover,
.fa-ellipsis:hover {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
  border: none !important;
  outline: none !important;
  background-color: transparent !important;
}
/* 去阴影，小眼睛、小星星 */
.menu_button, .fa-eye, .fa-ranking-star {
    text-shadow: none !important;
    box-shadow: none !important;
    filter: none !important; 
}




/*哈基米赞助去阴影别动！*/
